#include <cuda_runtime.h>
#include <cstdio>
#include <vector>

#define CUDA_CHECK(call) do { \
    cudaError_t err = (call); \
    if (err != cudaSuccess) { \
        fprintf(stderr, "CUDA ERROR: %s\n", \
                cudaGetErrorString(err)); \
        return 1; \
    } \
} while (0)

__global__ void vector_add(
    const int* a,
    const int* b,
    int* c,
    int n
) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        c[i] = a[i] + b[i];
    }
}

int main() {
    int device = 0;
    cudaDeviceProp prop;

    CUDA_CHECK(cudaSetDevice(device));
    CUDA_CHECK(cudaGetDeviceProperties(&prop, device));

    printf("GPU: %s\n", prop.name);
    printf("Compute Capability: %d.%d\n",
           prop.major, prop.minor);

    const int N = 1 << 20;
    size_t bytes = N * sizeof(int);

    std::vector<int> a(N, 10);
    std::vector<int> b(N, 20);
    std::vector<int> c(N, 0);

    int *da, *db, *dc;

    CUDA_CHECK(cudaMalloc(&da, bytes));
    CUDA_CHECK(cudaMalloc(&db, bytes));
    CUDA_CHECK(cudaMalloc(&dc, bytes));

    CUDA_CHECK(cudaMemcpy(da, a.data(), bytes,
                          cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(db, b.data(), bytes,
                          cudaMemcpyHostToDevice));

    vector_add<<<(N + 255) / 256, 256>>>(da, db, dc, N);

    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaDeviceSynchronize());

    CUDA_CHECK(cudaMemcpy(c.data(), dc, bytes,
                          cudaMemcpyDeviceToHost));

    for (int i = 0; i < N; i++) {
        if (c[i] != 30) {
            fprintf(stderr, "VERIFY FAILED at %d\n", i);
            return 1;
        }
    }

    printf("CUDA_KERNEL=PASS\n");
    printf("ELEMENTS=%d\n", N);
    printf("RESULT=%d\n", c[0]);

    cudaFree(da);
    cudaFree(db);
    cudaFree(dc);

    return 0;
}

// Variant A: int4 (128-bit) vectorized vector_add, same semantics as baseline.
// Each thread adds 4 ints. Verifies every element == 30 and prints a checksum.
#include <cuda_runtime.h>
#include <cstdio>
#include <vector>

#define CUDA_CHECK(call) do { \
    cudaError_t err = (call); \
    if (err != cudaSuccess) { \
        fprintf(stderr, "CUDA ERROR: %s\n", cudaGetErrorString(err)); \
        return 1; \
    } \
} while (0)

__global__ void vector_add_vec4(const int4* __restrict__ a,
                                const int4* __restrict__ b,
                                int4* __restrict__ c,
                                int n4) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n4) {
        int4 va = a[i];
        int4 vb = b[i];
        int4 vc;
        vc.x = va.x + vb.x;
        vc.y = va.y + vb.y;
        vc.z = va.z + vb.z;
        vc.w = va.w + vb.w;
        c[i] = vc;
    }
}

int main() {
    int device = 0;
    cudaDeviceProp prop;
    CUDA_CHECK(cudaSetDevice(device));
    CUDA_CHECK(cudaGetDeviceProperties(&prop, device));
    printf("GPU: %s\n", prop.name);
    printf("Compute Capability: %d.%d\n", prop.major, prop.minor);

    const int N = 1 << 20;
    const int N4 = N / 4;
    size_t bytes = N * sizeof(int);

    std::vector<int> a(N, 10), b(N, 20), c(N, 0);

    int *da = nullptr, *db = nullptr, *dc = nullptr;
    CUDA_CHECK(cudaMalloc(&da, bytes));
    CUDA_CHECK(cudaMalloc(&db, bytes));
    CUDA_CHECK(cudaMalloc(&dc, bytes));
    CUDA_CHECK(cudaMemcpy(da, a.data(), bytes, cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(db, b.data(), bytes, cudaMemcpyHostToDevice));

    const int threads = 128;
    vector_add_vec4<<<(N4 + threads - 1) / threads, threads>>>(
        reinterpret_cast<const int4*>(da),
        reinterpret_cast<const int4*>(db),
        reinterpret_cast<int4*>(dc), N4);

    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaDeviceSynchronize());
    CUDA_CHECK(cudaMemcpy(c.data(), dc, bytes, cudaMemcpyDeviceToHost));

    long long checksum = 0;
    for (int i = 0; i < N; i++) {
        if (c[i] != 30) {
            fprintf(stderr, "VERIFY FAILED at %d (got %d)\n", i, c[i]);
            return 1;
        }
        checksum += c[i];
    }

    printf("CUDA_KERNEL=PASS\n");
    printf("ELEMENTS=%d\n", N);
    printf("RESULT=%d\n", c[0]);
    printf("CHECKSUM=%lld\n", checksum);
    printf("EXPECTED_CHECKSUM=%lld\n", 30LL * N);
    printf("VARIANT=int4_vec4\n");

    cudaFree(da); cudaFree(db); cudaFree(dc);
    return 0;
}

// Variant B (negative control): identical to the baseline except index 12345
// is deliberately computed wrong. It exists to prove the verification loop
// actually detects a wrong result instead of printing PASS unconditionally.
#include <cuda_runtime.h>
#include <cstdio>
#include <vector>

#define CUDA_CHECK(call) do { \
    cudaError_t err = (call); \
    if (err != cudaSuccess) { \
        fprintf(stderr, "CUDA ERROR: %s\n", cudaGetErrorString(err)); \
        return 1; \
    } \
} while (0)

__global__ void vector_add_broken(const int* a, const int* b, int* c, int n) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        int v = a[i] + b[i];
        if (i == 12345) v += 1;   /* injected defect */
        c[i] = v;
    }
}

int main() {
    int device = 0;
    cudaDeviceProp prop;
    CUDA_CHECK(cudaSetDevice(device));
    CUDA_CHECK(cudaGetDeviceProperties(&prop, device));
    printf("GPU: %s\n", prop.name);
    printf("Compute Capability: %d.%d\n", prop.major, prop.minor);

    const int N = 1 << 20;
    size_t bytes = N * sizeof(int);
    std::vector<int> a(N, 10), b(N, 20), c(N, 0);

    int *da = nullptr, *db = nullptr, *dc = nullptr;
    CUDA_CHECK(cudaMalloc(&da, bytes));
    CUDA_CHECK(cudaMalloc(&db, bytes));
    CUDA_CHECK(cudaMalloc(&dc, bytes));
    CUDA_CHECK(cudaMemcpy(da, a.data(), bytes, cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(db, b.data(), bytes, cudaMemcpyHostToDevice));

    vector_add_broken<<<(N + 255) / 256, 256>>>(da, db, dc, N);

    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaDeviceSynchronize());
    CUDA_CHECK(cudaMemcpy(c.data(), dc, bytes, cudaMemcpyDeviceToHost));

    int bad = 0;
    for (int i = 0; i < N; i++) {
        if (c[i] != 30) {
            if (bad == 0) fprintf(stderr, "VERIFY FAILED at %d (got %d)\n", i, c[i]);
            bad++;
        }
    }

    printf("MISMATCH_COUNT=%d\n", bad);
    if (bad != 0) {
        printf("CUDA_KERNEL=FAIL\n");
        printf("VARIANT=injected_defect\n");
        return 1;
    }
    printf("CUDA_KERNEL=PASS\n");
    printf("VARIANT=injected_defect\n");
    return 0;
}
